"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { ChangeEvent } from "react";
import {
  Copy,
  Check,
  Plus,
  Trash2,
  Download,
  Upload,
  ChevronDown,
  AlertCircle,
  Info,
} from "lucide-react";

/* ------------------------------------------------------------------ */
/* Data: ISO 639-1 language codes and ISO 3166-1 alpha-2 country codes */
/* Names are generated by the browser, so code and name always match.  */
/* ------------------------------------------------------------------ */

const LANGUAGE_CODES =
  "aa ab ae af ak am an ar as av ay az ba be bg bh bi bm bn bo br bs ca ce ch co cr cs cu cv cy da de dv dz ee el en eo es et eu fa ff fi fj fo fr fy ga gd gl gn gu gv ha he hi ho hr ht hu hy hz ia id ie ig ii ik io is it iu ja jv ka kg ki kj kk kl km kn ko kr ks ku kv kw ky la lb lg li ln lo lt lu lv mg mh mi mk ml mn mr ms mt my na nb nd ne ng nl nn no nr nv ny oc oj om or os pa pi pl ps pt qu rm rn ro ru rw sa sc sd se sg si sk sl sm sn so sq sr ss st su sv sw ta te tg th ti tk tl tn to tr ts tt tw ty ug uk ur uz ve vi vo wa wo xh yi yo za zh zu".split(
    " "
  );

const COUNTRY_CODES =
  "AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW".split(
    " "
  );

interface Option {
  value: string;
  label: string;
}

/** Builds a sorted option list. Falls back to the plain code if the browser has no name for it. */
function buildOptions(codes: string[], type: "language" | "region"): Option[] {
  let names: Intl.DisplayNames | null = null;
  try {
    names = new Intl.DisplayNames(["en"], { type, fallback: "none" });
  } catch {
    names = null;
  }
  const list: Option[] = [];
  for (const code of codes) {
    const name = names ? names.of(code) : code;
    if (name) list.push({ value: code.toLowerCase(), label: name });
  }
  return list.sort((a, b) => a.label.localeCompare(b.label));
}

const LANGUAGE_OPTIONS: Option[] = buildOptions(LANGUAGE_CODES, "language");
const COUNTRY_OPTIONS: Option[] = [
  { value: "", label: "No country (language only)" },
  ...buildOptions(COUNTRY_CODES, "region"),
];

/* ------------------------------------------------------------------ */
/* Helpers                                                              */
/* ------------------------------------------------------------------ */

const MAX_URLS = 50;

interface Version {
  id: number;
  url: string;
  lang: string; // for example "en"
  country: string; // for example "us" (optional)
}

interface Entry {
  code: string; // for example "en-us" or "x-default"
  url: string;
}

type Format = "html" | "xml";

/** True when the value is a full http or https address. */
function isValidUrl(value: string): boolean {
  try {
    const u = new URL(value.trim());
    return u.protocol === "http:" || u.protocol === "https:";
  } catch {
    return false;
  }
}

/** Escapes characters that are not allowed inside HTML or XML attribute values. */
function esc(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

/** Language plus optional country, always lowercase: en, en-us, ur-pk. */
function makeCode(lang: string, country: string): string {
  return country ? `${lang}-${country}`.toLowerCase() : lang.toLowerCase();
}

function buildHtml(entries: Entry[]): string {
  return entries
    .map((e) => `<link rel="alternate" hreflang="${e.code}" href="${esc(e.url)}" />`)
    .join("\n");
}

function buildXml(entries: Entry[]): string {
  const links = entries
    .map((e) => `    <xhtml:link rel="alternate" hreflang="${e.code}" href="${esc(e.url)}" />`)
    .join("\n");
  const pages = Array.from(new Set(entries.map((e) => e.url)));
  const urls = pages
    .map((loc) => `  <url>\n    <loc>${esc(loc)}</loc>\n${links}\n  </url>`)
    .join("\n");
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n${urls}\n</urlset>`;
}

/* ------------------------------------------------------------------ */
/* Shared styles                                                        */
/* ------------------------------------------------------------------ */

const labelClass = "text-xs font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300";
const inputClass =
  "w-full rounded-md border border-slate-300 bg-white px-4 py-3 text-base text-slate-900 placeholder-slate-400 outline-none transition-colors focus:border-accent-500 focus:ring-2 focus:ring-accent-500/20 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100";
const toggleBase = "rounded-md border px-4 py-2 text-sm font-bold transition-colors";
const toggleActive =
  "border-indigo-700 bg-indigo-700 text-white dark:border-accent-500 dark:bg-accent-500";
const toggleIdle =
  "border-slate-300 bg-white text-slate-700 hover:border-accent-500 hover:text-accent-600 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200 dark:hover:text-accent-400";
const secondaryBtn =
  "inline-flex items-center gap-2 rounded-md border border-slate-300 bg-white px-4 py-2.5 text-sm font-bold text-slate-700 transition-colors hover:border-accent-500 hover:text-accent-600 disabled:cursor-not-allowed disabled:opacity-50 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200";
const mainBtn =
  "inline-flex items-center gap-2 rounded-md bg-accent-500 px-6 py-3 text-sm font-bold text-white transition-colors hover:bg-accent-600 disabled:cursor-not-allowed disabled:opacity-50";

/* ------------------------------------------------------------------ */
/* Searchable dropdown                                                  */
/* ------------------------------------------------------------------ */

function SearchSelect({
  label,
  value,
  options,
  placeholder,
  onChange,
}: {
  label: string;
  value: string;
  options: Option[];
  placeholder: string;
  onChange: (value: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const boxRef = useRef<HTMLDivElement>(null);

  // Close the list when the user clicks outside of it.
  useEffect(() => {
    if (!open) return;
    function onClick(e: MouseEvent) {
      if (boxRef.current && !boxRef.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  const q = query.trim().toLowerCase();
  const filtered = q
    ? options.filter((o) => o.label.toLowerCase().includes(q) || o.value.includes(q))
    : options;
  const selected = options.find((o) => o.value === value);

  function choose(next: string) {
    onChange(next);
    setOpen(false);
    setQuery("");
  }

  return (
    <div
      ref={boxRef}
      className="relative"
      onKeyDown={(e) => {
        if (e.key === "Escape") setOpen(false);
      }}
    >
      <span className={`mb-1.5 block ${labelClass}`}>{label}</span>
      <button
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label={label}
        onClick={() => setOpen((o) => !o)}
        className="flex w-full items-center justify-between gap-2 rounded-md border border-slate-300 bg-white px-4 py-3 text-left text-base outline-none transition-colors hover:border-accent-500 focus:border-accent-500 focus:ring-2 focus:ring-accent-500/20 dark:border-slate-700 dark:bg-slate-900"
      >
        <span className={selected && value ? "text-slate-900 dark:text-slate-100" : "text-slate-400"}>
          {selected ? selected.label : placeholder}
        </span>
        <ChevronDown className="h-4 w-4 shrink-0 text-slate-500" aria-hidden="true" />
      </button>

      {open && (
        <div className="absolute z-30 mt-1 w-full rounded-md border border-slate-300 bg-white dark:border-slate-700 dark:bg-slate-900">
          <input
            autoFocus
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                if (filtered.length > 0) choose(filtered[0].value);
              }
            }}
            placeholder="Type to search..."
            aria-label={`Search ${label}`}
            className="w-full border-b border-slate-200 bg-transparent px-4 py-2.5 text-base text-slate-900 placeholder-slate-400 outline-none dark:border-slate-700 dark:text-slate-100"
          />
          <ul role="listbox" aria-label={label} className="max-h-60 overflow-y-auto py-1">
            {filtered.length === 0 && (
              <li role="presentation" className="px-4 py-2 text-sm text-slate-500">
                No match found.
              </li>
            )}
            {filtered.map((o) => (
              <li key={o.value || "none"} role="presentation">
                <button
                  type="button"
                  role="option"
                  aria-selected={o.value === value}
                  onClick={() => choose(o.value)}
                  className={`flex w-full items-center justify-between gap-3 px-4 py-2 text-left text-base hover:bg-slate-100 dark:hover:bg-slate-800 ${
                    o.value === value
                      ? "font-bold text-indigo-700 dark:text-accent-400"
                      : "text-slate-800 dark:text-slate-200"
                  }`}
                >
                  <span>{o.label}</span>
                  {o.value && <span className="font-mono text-xs uppercase text-slate-400">{o.value}</span>}
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Main component                                                       */
/* ------------------------------------------------------------------ */

export default function HreflangTagGeneratorUI() {
  const idRef = useRef(3);
  const [rows, setRows] = useState<Version[]>([
    { id: 1, url: "", lang: "en", country: "" },
    { id: 2, url: "", lang: "", country: "" },
  ]);
  const [useDefault, setUseDefault] = useState(true);
  const [defaultUrl, setDefaultUrl] = useState("");
  const [format, setFormat] = useState<Format>("html");
  const [csvMessage, setCsvMessage] = useState("");
  const [copied, setCopied] = useState(false);

  function newRow(patch: Partial<Version> = {}): Version {
    const id = idRef.current;
    idRef.current += 1;
    return { id, url: "", lang: "", country: "", ...patch };
  }

  function updateRow(id: number, patch: Partial<Version>) {
    setRows((prev) => prev.map((r) => (r.id === id ? { ...r, ...patch } : r)));
  }

  function addRow() {
    if (rows.length >= MAX_URLS) return;
    const row = newRow();
    setRows((prev) => [...prev, row]);
  }

  function removeRow(id: number) {
    setRows((prev) => (prev.length > 1 ? prev.filter((r) => r.id !== id) : prev));
  }

  function resetAll() {
    setRows([newRow({ lang: "en" })]);
    setUseDefault(true);
    setDefaultUrl("");
    setCsvMessage("");
  }

  /** Reads a CSV file: first column = URL, one URL per line. */
  function handleCsv(e: ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    e.target.value = ""; // allow choosing the same file again
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      const lines = String(reader.result || "")
        .split(/\r?\n/)
        .map((line) => line.split(/[,;\t]/)[0].trim().replace(/^["']|["']$/g, ""))
        .filter(Boolean);
      const urls = lines.filter(isValidUrl);
      const skipped = lines.length - urls.length;
      if (urls.length === 0) {
        setCsvMessage(
          "No valid URLs found. The file needs one column with full addresses that start with https://"
        );
        return;
      }
      const used = urls.slice(0, MAX_URLS);
      setRows(used.map((url) => newRow({ url })));
      let message = `Imported ${used.length} URL${used.length === 1 ? "" : "s"}. Now choose a language for each one.`;
      if (urls.length > MAX_URLS) message += ` Only the first ${MAX_URLS} were imported.`;
      if (skipped > 0) message += ` ${skipped} line${skipped === 1 ? " was" : "s were"} skipped (not a full URL, for example a header row).`;
      setCsvMessage(message);
    };
    reader.readAsText(file);
  }

  /* Validate everything and build the list of tags. */
  const { errors, warnings, entries } = useMemo(() => {
    const errs: string[] = [];
    const warns: string[] = [];
    const list: Entry[] = [];
    const urlSeen = new Map<string, number>();
    const codeSeen = new Map<string, number>();

    rows.forEach((r, index) => {
      const n = index + 1;
      const url = r.url.trim();
      if (!url) return; // empty rows are ignored

      if (!isValidUrl(url)) {
        errs.push(`Version ${n}: "${url}" is not a valid URL. Use a full address like https://example.com/page`);
        return;
      }
      if (url.toLowerCase().startsWith("http://")) {
        warns.push(`Version ${n}: this URL uses http. Use https if your site supports it.`);
      }
      if (!r.lang) {
        errs.push(`Version ${n}: choose a language.`);
        return;
      }
      const code = makeCode(r.lang, r.country);
      const sameUrl = urlSeen.get(url.toLowerCase());
      if (sameUrl) {
        errs.push(`Version ${n}: this URL is already used in version ${sameUrl}. Each version needs its own URL.`);
        return;
      }
      const sameCode = codeSeen.get(code);
      if (sameCode) {
        errs.push(
          `Version ${n}: "${code}" is already used in version ${sameCode}. Each language and country pair can be used only once.`
        );
        return;
      }
      urlSeen.set(url.toLowerCase(), n);
      codeSeen.set(code, n);
      list.push({ code, url });
    });

    if (list.length === 1 && errs.length === 0) {
      warns.push("Add at least one more version. Hreflang works when two or more versions list each other.");
    }

    if (useDefault) {
      const d = defaultUrl.trim();
      if (!d) {
        warns.push("x-default is switched on but no URL is entered. Enter a URL or switch it off.");
      } else if (!isValidUrl(d)) {
        errs.push(`x-default: "${d}" is not a valid URL. Use a full address like https://example.com/`);
      } else {
        list.push({ code: "x-default", url: d });
      }
    }

    return { errors: errs, warnings: warns, entries: list };
  }, [rows, useDefault, defaultUrl]);

  const output = useMemo(() => {
    if (errors.length > 0 || entries.length === 0) return "";
    return format === "html" ? buildHtml(entries) : buildXml(entries);
  }, [errors, entries, format]);

  async function handleCopy() {
    if (!output) return;
    try {
      await navigator.clipboard.writeText(output);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard not available */
    }
  }

  function handleDownload() {
    if (!output) return;
    const blob = new Blob([output], { type: "application/xml" });
    const href = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = href;
    a.download = "hreflang-sitemap.xml";
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(href);
  }

  const firstUrl = rows.find((r) => r.url.trim())?.url.trim() || "";

  return (
    <div className="space-y-8">
      {/* Help */}
      <div className="rounded-md border border-slate-200 bg-slate-50 p-5 dark:border-slate-800 dark:bg-slate-900">
        <p className="mb-3 flex items-center gap-2 font-serif text-lg font-bold text-slate-900 dark:text-slate-100">
          <Info className="h-5 w-5 text-accent-500" aria-hidden="true" />
          Before you start: 3 simple rules
        </p>
        <ul className="list-disc space-y-1.5 pl-5 text-base text-slate-700 dark:text-slate-300">
          <li>
            Every page must list <strong>all</strong> versions, including <strong>itself</strong>. This is called a
            self-reference.
          </li>
          <li>The same set of tags must be placed on every language version of the page.</li>
          <li>Always use full URLs that start with https:// (not /page or page.html).</li>
        </ul>
      </div>

      {/* Step 1: versions */}
      <section aria-labelledby="hl-step1" className="space-y-4">
        <h3 id="hl-step1" className="font-serif text-xl font-bold text-slate-900 dark:text-slate-100">
          1. Add your page versions
        </h3>

        <div className="flex flex-wrap items-center gap-3">
          <label className={`${secondaryBtn} cursor-pointer`}>
            <Upload className="h-4 w-4" aria-hidden="true" />
            Fill the list from a CSV file
            <input type="file" accept=".csv,.txt,text/csv,text/plain" onChange={handleCsv} className="sr-only" />
          </label>
          <span className="text-sm text-slate-600 dark:text-slate-400">
            One column of URLs, up to {MAX_URLS} URLs.
          </span>
        </div>
        {csvMessage && (
          <p role="status" className="rounded-md border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-700 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-300">
            {csvMessage}
          </p>
        )}

        <div className="space-y-4">
          {rows.map((row, index) => (
            <div
              key={row.id}
              className="rounded-md border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-900"
            >
              <div className="mb-3 flex items-center justify-between">
                <p className="font-serif text-base font-bold text-slate-900 dark:text-slate-100">
                  Version {index + 1}
                </p>
                <button
                  type="button"
                  onClick={() => removeRow(row.id)}
                  disabled={rows.length <= 1}
                  aria-label={`Remove version ${index + 1}`}
                  className="inline-flex items-center gap-1.5 text-sm font-bold text-slate-600 hover:text-accent-600 disabled:cursor-not-allowed disabled:opacity-40 dark:text-slate-400"
                >
                  <Trash2 className="h-4 w-4" aria-hidden="true" />
                  Remove
                </button>
              </div>

              <label htmlFor={`hl-url-${row.id}`} className={`mb-1.5 block ${labelClass}`}>
                Page URL
              </label>
              <input
                id={`hl-url-${row.id}`}
                type="text"
                value={row.url}
                onChange={(e) => updateRow(row.id, { url: e.target.value })}
                placeholder="https://example.com/page"
                autoComplete="off"
                className={inputClass}
              />

              <div className="mt-4 grid gap-4 sm:grid-cols-2">
                <SearchSelect
                  label="Language"
                  value={row.lang}
                  options={LANGUAGE_OPTIONS}
                  placeholder="Select language"
                  onChange={(lang) => updateRow(row.id, { lang })}
                />
                <SearchSelect
                  label="Country (optional)"
                  value={row.country}
                  options={COUNTRY_OPTIONS}
                  placeholder="No country (language only)"
                  onChange={(country) => updateRow(row.id, { country })}
                />
              </div>
            </div>
          ))}
        </div>

        <div className="flex flex-wrap gap-3">
          <button type="button" onClick={addRow} disabled={rows.length >= MAX_URLS} className={secondaryBtn}>
            <Plus className="h-4 w-4" aria-hidden="true" />
            Add another language / country version
          </button>
          <button type="button" onClick={resetAll} className={secondaryBtn}>
            <Trash2 className="h-4 w-4" aria-hidden="true" />
            Remove all and start clean
          </button>
        </div>
        <p className="text-sm text-slate-600 dark:text-slate-400">
          Tip: choose only a language (for example English) when the page is for everyone who speaks it. Add a
          country only when the page is for one country (for example English + United States).
        </p>
      </section>

      {/* Step 2: x-default */}
      <section aria-labelledby="hl-step2" className="space-y-3">
        <h3 id="hl-step2" className="font-serif text-xl font-bold text-slate-900 dark:text-slate-100">
          2. Default page (x-default)
        </h3>
        <p className="text-base text-slate-700 dark:text-slate-300">
          This is the page shown to people whose language is <strong>not</strong> in your list. It is usually your
          main page or a language chooser page. We recommend keeping it on.
        </p>
        <label className="flex items-center gap-2 text-base text-slate-700 dark:text-slate-300">
          <input
            type="checkbox"
            checked={useDefault}
            onChange={(e) => setUseDefault(e.target.checked)}
            className="h-4 w-4 rounded border-slate-300 accent-accent-500"
          />
          Add an x-default page
        </label>
        {useDefault && (
          <div className="flex flex-col gap-3 sm:flex-row">
            <input
              type="text"
              value={defaultUrl}
              onChange={(e) => setDefaultUrl(e.target.value)}
              placeholder="https://example.com/"
              aria-label="x-default page URL"
              autoComplete="off"
              className={inputClass}
            />
            <button
              type="button"
              onClick={() => setDefaultUrl(firstUrl)}
              disabled={!firstUrl}
              className={`${secondaryBtn} shrink-0 justify-center`}
            >
              Use the first URL
            </button>
          </div>
        )}
      </section>

      {/* Step 3: format + output */}
      <section aria-labelledby="hl-step3" className="space-y-4">
        <h3 id="hl-step3" className="font-serif text-xl font-bold text-slate-900 dark:text-slate-100">
          3. Get your code
        </h3>

        <div>
          <p id="hl-format-label" className={`mb-2 ${labelClass}`}>
            Output format
          </p>
          <div role="group" aria-labelledby="hl-format-label" className="flex flex-wrap gap-2">
            <button
              type="button"
              aria-pressed={format === "html"}
              onClick={() => setFormat("html")}
              className={`${toggleBase} ${format === "html" ? toggleActive : toggleIdle}`}
            >
              HTML head tags
            </button>
            <button
              type="button"
              aria-pressed={format === "xml"}
              onClick={() => setFormat("xml")}
              className={`${toggleBase} ${format === "xml" ? toggleActive : toggleIdle}`}
            >
              XML sitemap
            </button>
          </div>
          <p className="mt-2 text-sm text-slate-600 dark:text-slate-400">
            {format === "html"
              ? "Paste the tags inside the <head> of every page listed above."
              : "Save the file as sitemap.xml (or add it to your existing sitemap) and submit it in Google Search Console."}
          </p>
        </div>

        {errors.length > 0 && (
          <div
            role="alert"
            className="space-y-1.5 rounded-md border border-red-200 bg-red-50 p-4 text-sm text-red-800 dark:border-red-900 dark:bg-red-950 dark:text-red-200"
          >
            {errors.map((m) => (
              <p key={m} className="flex items-start gap-2">
                <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />
                {m}
              </p>
            ))}
          </div>
        )}

        {warnings.length > 0 && (
          <div className="space-y-1.5 rounded-md border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800 dark:border-amber-900 dark:bg-amber-950 dark:text-amber-200">
            {warnings.map((m) => (
              <p key={m} className="flex items-start gap-2">
                <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />
                {m}
              </p>
            ))}
          </div>
        )}

        <div className="rounded-md border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900">
          <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
            <p className={labelClass}>Your hreflang {format === "html" ? "tags" : "sitemap"}</p>
            <div className="flex flex-wrap gap-2">
              <button
                type="button"
                onClick={handleCopy}
                disabled={!output}
                className={`inline-flex items-center gap-2 rounded-md px-5 py-2.5 text-sm font-bold text-white disabled:cursor-not-allowed disabled:opacity-50 ${
                  copied ? "bg-emerald-600 hover:bg-emerald-700" : "bg-accent-500 hover:bg-accent-600"
                }`}
              >
                {copied ? (
                  <Check className="h-4 w-4" aria-hidden="true" />
                ) : (
                  <Copy className="h-4 w-4" aria-hidden="true" />
                )}
                {copied ? "Copied!" : "Copy"}
              </button>
              {format === "xml" && (
                <button type="button" onClick={handleDownload} disabled={!output} className={secondaryBtn}>
                  <Download className="h-4 w-4" aria-hidden="true" />
                  Download .xml
                </button>
              )}
            </div>
          </div>
          <pre className="overflow-x-auto whitespace-pre rounded-md border border-slate-200 bg-slate-50 p-4 font-mono text-sm leading-relaxed text-slate-800 dark:border-slate-800 dark:bg-slate-950 dark:text-slate-200">
            {output ||
              (errors.length > 0
                ? "Fix the problems above to see your code."
                : "Add a URL and a language for each version and your code will appear here.")}
          </pre>
        </div>
      </section>
    </div>
  );
}